# Recon — the code-modularity audit and the move tools (2026-10-26)

The blueprint and tools that `PLAN-2026-10-26-modularity` runs on, stored as a record so a session on any box has them (cold read G10, D5). The audits are the explorer's of 2026-10-26, verbatim: their line ranges and sizes are estimates at their commit (cf1713c's parent tree), re-counted before each phase. Audit 1 (`internal/eval/run.go`) was done at 52259a5 and is left out. Two corrections the cold read (`REVIEW-2026-10-26-1135-review-cold-read-of-the-code-modularity-plan-202`) made to how they are read: a grouped `var`/`const` block moves whole (plan D2), and a method is named `Type.method` in a `declmove` list (plan D4).

## The move tools

Rebuild them with `mkdir -p .agents/scratch/declmove .agents/scratch/declsum` and each source below as that directory's `main.go`; run with `go run ./.agents/scratch/declmove …` and `go run ./.agents/scratch/declsum …`.

### .agents/scratch/declmove/main.go

```go
// declmove moves whole top-level declarations (with their doc comments) of
// one Go file into sibling files of the same package, byte for byte. Usage:
// declmove <file> <target.go>=<name>,<name>... ; a name not listed stays.
// Every target gets the source's full import block; prune with the compiler.
// A method is named Type.method; a var/const/type group moves whole, and
// naming two of its members for two targets panics. Comments between
// declarations travel with the declaration after them. Targets are written
// before the source and an existing target panics: restore with git on failure.
package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"strings"
)

func names(d ast.Decl) []string {
	switch d := d.(type) {
	case *ast.FuncDecl:
		// A method is keyed Type.method, so it never collides with a
		// function or type of the same name (cold read G8d).
		if d.Recv != nil && len(d.Recv.List) > 0 {
			t := d.Recv.List[0].Type
			if s, ok := t.(*ast.StarExpr); ok {
				t = s.X
			}
			switch x := t.(type) {
			case *ast.IndexExpr:
				t = x.X
			case *ast.IndexListExpr:
				t = x.X
			}
			if id, ok := t.(*ast.Ident); ok {
				return []string{id.Name + "." + d.Name.Name}
			}
		}
		return []string{d.Name.Name}
	case *ast.GenDecl:
		var out []string
		for _, s := range d.Specs {
			switch s := s.(type) {
			case *ast.TypeSpec:
				out = append(out, s.Name.Name)
			case *ast.ValueSpec:
				for _, n := range s.Names {
					out = append(out, n.Name)
				}
			}
		}
		return out
	}
	return nil
}

func main() {
	src := os.Args[1]
	b, err := os.ReadFile(src)
	if err != nil {
		panic(err)
	}
	fs := token.NewFileSet()
	f, err := parser.ParseFile(fs, src, b, parser.ParseComments)
	if err != nil {
		panic(err)
	}
	target := map[string]string{}
	var order []string
	for _, a := range os.Args[2:] {
		t, list, _ := strings.Cut(a, "=")
		order = append(order, t)
		for _, n := range strings.Split(list, ",") {
			target[n] = t
		}
	}
	var imports ast.Decl
	parts := map[string][]string{}
	keep := []string{}
	used := map[string]bool{}
	// prev is the end of the last declaration (import included): a
	// declaration's text starts there, so a comment group detached from any
	// declaration travels with the one after it, never dropped (cold read G2).
	prev := -1
	for _, d := range f.Decls {
		if g, ok := d.(*ast.GenDecl); ok && g.Tok == token.IMPORT {
			imports = d
			prev = fs.Position(d.End()).Offset
			continue
		}
		if prev < 0 {
			panic("a declaration before the import block")
		}
		text := strings.TrimLeft(string(b[prev:fs.Position(d.End()).Offset]), "\n")
		prev = fs.Position(d.End()).Offset
		ns := names(d)
		t := ""
		for _, n := range ns {
			if x, ok := target[n]; ok {
				if t != "" && t != x {
					panic(fmt.Sprintf("decl %v split across targets", ns))
				}
				t = x
				used[n] = true
			}
		}
		if t == "" {
			keep = append(keep, text)
		} else {
			parts[t] = append(parts[t], text)
		}
	}
	for n := range target {
		if !used[n] {
			panic("no declaration named " + n)
		}
	}
	if tail := strings.TrimSpace(string(b[prev:])); tail != "" {
		keep = append(keep, tail)
	}
	if strings.Count(string(b), "\nimport ") > 1 {
		panic("more than one import declaration")
	}
	imp := string(b[fs.Position(imports.Pos()).Offset:fs.Position(imports.End()).Offset])
	// The source keeps every byte up to the end of its import block: build
	// tags, the package doc and any comment between the clause and imports.
	head := string(b[:fs.Position(imports.End()).Offset]) + "\n\n"
	dir := filepath.Dir(src)
	for _, t := range order {
		p := filepath.Join(dir, t)
		if _, err := os.Stat(p); err == nil {
			panic(p + " exists")
		}
		if err := os.WriteFile(p, []byte("package "+f.Name.Name+"\n\n"+imp+"\n\n"+strings.Join(parts[t], "\n\n")+"\n"), 0o644); err != nil {
			panic(err)
		}
	}
	if err := os.WriteFile(src, []byte(head+strings.Join(keep, "\n\n")+"\n"), 0o644); err != nil {
		panic(err)
	}
}
```

### .agents/scratch/declsum/main.go

```go
// declsum prints a sha256 per non-import top-level declaration (doc comment
// included) and per comment group of the given files, sorted, so two file
// sets can be compared: equal output means no declaration and no comment was
// changed or lost.
package main

import (
	"crypto/sha256"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"sort"
)

func main() {
	var out []string
	for _, p := range os.Args[1:] {
		b, _ := os.ReadFile(p)
		fs := token.NewFileSet()
		f, err := parser.ParseFile(fs, p, b, parser.ParseComments)
		if err != nil {
			panic(err)
		}
		for _, d := range f.Decls {
			if g, ok := d.(*ast.GenDecl); ok && g.Tok == token.IMPORT {
				continue
			}
			start := d.Pos()
			if fd, ok := d.(*ast.FuncDecl); ok && fd.Doc != nil {
				start = fd.Doc.Pos()
			}
			if gd, ok := d.(*ast.GenDecl); ok && gd.Doc != nil {
				start = gd.Doc.Pos()
			}
			out = append(out, fmt.Sprintf("decl %x", sha256.Sum256(b[fs.Position(start).Offset:fs.Position(d.End()).Offset])))
		}
		// Every comment group, attached or not, so a comment a move drops
		// shows as a missing line (cold read G2). The package doc is one.
		for _, c := range f.Comments {
			out = append(out, fmt.Sprintf("comment %x", sha256.Sum256(b[fs.Position(c.Pos()).Offset:fs.Position(c.End()).Offset])))
		}
	}
